const title = ev.summary || '(no title)';
if (!ref) return bad('NO_REFERENCE',
  'BLOCKED - "' + title + '" carries no booker reference, so there is no way to tell whose it is. It has to be moved by hand.');
// --- who may move this: the owner, or an authorized coordinator in the booking's department ---
// Authorized roles are the explicit exception to Rule 1. Phase 1: Bookers Authority of
// 'Dept Head' or 'Client Booking', acting within their own department. Howard is hard-coded as a
// test coordinator for the weekend; real tags land in Airtable on Monday, then drop this line and
// narrow the rule. See docs/design/booking-authority.md.
const TEST_COORD = { 'U08V3CKDGJF': true };
const authStr = String(REQ.authority || '').toLowerCase();
const isCoord = authStr.indexOf('dept head') !== -1 || authStr.indexOf('client booking') !== -1 || TEST_COORD[me] === true;
const myDepts = String(REQ.department || '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const bookingDept = ((desc.match(/Dept:\s*([^|]+)/) || [])[1] || '').toLowerCase().trim();
const owner = ref[1] === me;
const isHaistDev = authStr.indexOf('haist dev') !== -1;
const coordInDept = isCoord && !!bookingDept && myDepts.indexOf(bookingDept) !== -1;
if (!(owner || isHaistDev || coordInDept)) return bad('NOT_YOURS',
  'BLOCKED - "' + title + '" was booked by ' + ((by && by[1].trim()) || 'someone else')
  + ', and you do not have authority to move it. Say exactly that and stop.');

// Optional room change: relocate to a different room. Empty new_rooms keeps the original room
// (a plain time reschedule is unchanged). A room change swaps the resource attendees and the
// location, so Check New Window then checks the NEW room and Create Replacement books it there.
let outLocation = ev.location || '';
let outAttendees = (ev.attendees || []).filter(a => a.resource).map(a => ({ email: a.email }));
const ROOMS = {'Studio 1':'hitproductions.net_3737303833303637363538@resource.calendar.google.com','Studio 2':'c_18871bprki2umhrkjc4qcaldse1f8@resource.calendar.google.com','Studio 3':'c_1886me03bdcrki5bhu8vddknl472k@resource.calendar.google.com','Studio 4':'c_188e94dapvbp8jvrjmuga6qbof826@resource.calendar.google.com','Studio 5':'c_18889v3glj9cqiotg8j95jaqmdhmm@resource.calendar.google.com','Studio 6':'c_18838qt2ru30ein7gcefjiarplkre@resource.calendar.google.com','Studio 7':'c_188dupcj6cqfaipohqffj07ruq8de@resource.calendar.google.com','Studio 8':'c_18863v8hd6f42isegdh9i30psuo9q@resource.calendar.google.com','Studio A':'c_18843dclutqm6hl9nbeg002phapfu@resource.calendar.google.com','Studio B':'c_1881vgb66tkpujjelnn3rniugd9pk@resource.calendar.google.com','Studio C':'c_188797f37eu9ujs6ldpf3smn78joc@resource.calendar.google.com','Studio D':'c_18801gc6ck77gho7jl0e1fug94u92@resource.calendar.google.com','Studio E':'c_18807te03d2sqh0lmtal9sbb04gao@resource.calendar.google.com','Studio F':'c_188em7d58podeju3i8q6juqlufkls@resource.calendar.google.com','Studio M':'c_1885k4adm87fqjd2j3j2usqftph5c@resource.calendar.google.com','M1':'c_1889v46vd62fkjk3i7r1hsfem7tcm@resource.calendar.google.com','M2':'c_1883ui6lnfc9ogt2hrmg57a30n72q@resource.calendar.google.com','M3':'c_188d7dkqgnfs6hu4iunlu5ogftct0@resource.calendar.google.com','M4':'c_18869nhmsj2uki8mljoi48v1cj7l4@resource.calendar.google.com','M5':'c_1889h30ci9noqjcbnoogad9qk75vq@resource.calendar.google.com','M6':'c_188f9gnq0a9tehf4g9ja57l83c0ts@resource.calendar.google.com','M7':'c_1880r9hhk9c2agpbko87o7fojosh0@resource.calendar.google.com','M8':'c_1884cu2cc84iujsjnu03s21f0ct9q@resource.calendar.google.com','Salin':'c_1887hh5rsv6q4gt8hnu6ered170lg@resource.calendar.google.com','Katha':'c_1881169pcpn12gsnm6i7sc0gjk7gk@resource.calendar.google.com','Likha':'c_1886t6cjgrq0ihgpime01uibcqsg6@resource.calendar.google.com','Lobby':'c_188227mpeagjuhi7gqlgns1di14be@resource.calendar.google.com'};
const newRooms = String(REQ.new_rooms || '').split(/,|\band\b|&|\+/i).map(r => r.trim()).filter(Boolean);
if (newRooms.length) {
  const keys = Object.keys(ROOMS); const emails = [], names = [];
  for (const r of newRooms) {
    const hit = keys.find(k => k.toLowerCase() === r.toLowerCase());
    if (!hit) return bad('UNKNOWN_ROOM', 'Nothing was moved - "' + r + '" is not a room I recognise. Check the room name and try again.');
    emails.push(ROOMS[hit]); names.push(hit);
  }
  outLocation = names.join(', '); outAttendees = emails.map(e => ({ email: e }));
}
// Notify the booker (and assigned engineer, resolved downstream) when a coordinator
// - not the owner - moves their booking. Composition + dev redirect live in Build
// Recipients so they are unit-testable. See EOD-2026-09-19.
const notify = !owner && (coordInDept || isHaistDev);
const bookerRef = ref[1];
const bookerName = (by && by[1] && by[1].trim()) || 'the booker';
const engInitials = (title.split('/').pop() || '').trim();
const engName = ((desc.match(/Engineer:\s*([^(|]+)/) || [])[1] || '').trim();
const _q = s => String(s).replace(/"/g, '');
const _p = [];
if (engInitials) _p.push('{Initials} = "' + _q(engInitials) + '"');
if (engName) _p.push('LOWER({Name}) = "' + _q(engName).toLowerCase() + '"');
const engFilter = _p.length === 0 ? 'FALSE()' : (_p.length === 1 ? _p[0] : 'OR(' + _p.join(', ') + ')');
const roomNote = outLocation ? (' to ' + outLocation) : '';
return [{ json: { verdict:'CLEAR', matched_on: how, original_id: ev.id, title,
  description: desc, location: outLocation, attendees: outAttendees,
  old_start: (ev.start && (ev.start.dateTime || ev.start.date)) || '',
  new_start: REQ.new_start_iso, new_end: REQ.new_end_iso,
  notify, bookerRef, bookerName, engInitials, engFilter, roomNote } }];

// The new window has to be free for the same rooms - excluding the booking
// being moved, which would otherwise collide with itself.
const R = $('Resolve Booking').first().json;
const raw = $input.first().json || {};
const items = Array.isArray(raw.items) ? raw.items.filter(e => e.status !== 'cancelled') : [];
const mine = R.attendees.map(a => String(a.email).toLowerCase());
const loc = String(R.location || '').toLowerCase();
const ns = new Date(R.new_start).getTime(), ne = new Date(R.new_end).getTime();

const clashes = [];
for (const e of items) {
  if (String(e.id) === String(R.original_id)) continue;
  const s = new Date((e.start && (e.start.dateTime || e.start.date))).getTime();
  const t = new Date((e.end && (e.end.dateTime || e.end.date))).getTime();
  if (!(s < ne && t > ns)) continue;
  const emails = (e.attendees || []).map(a => String(a.email || '').toLowerCase());
  const sameRoom = mine.some(m => emails.indexOf(m) !== -1)
    || (loc && String(e.location || '').toLowerCase() === loc);
  if (sameRoom) clashes.push(e.summary || '(no title)');
}
if (clashes.length) {
  return [{ json: { verdict:'REJECTED', reason:'ROOM_OCCUPIED',
    human: 'Nothing was moved - that room is taken in the new window by "' + clashes.join('", "')
         + '". The original booking is untouched. Tell the requester and offer another time.' } }];
}
return [{ json: Object.assign({}, R, { verdict:'CLEAR' }) }];

const R = $('Resolve Booking').first().json;
const created = $('Create Replacement').first().json || {};
return [{ json: { status:'MOVED', event_id: created.id || '', title: R.title,
  from: R.old_start, to: R.new_start,
  human: 'Moved "' + R.title + '" to the new time. Tell the requester the new date and time.' } }];

// The replacement exists but the original could not be removed, so the room is
// now double-booked. Say so plainly - this is the one outcome nobody should
// discover from the calendar a week later.
const R = $('Resolve Booking').first().json;
const created = $('Create Replacement').first().json || {};
return [{ json: { status:'PARTIAL', reason:'ORIGINAL_NOT_REMOVED', event_id: created.id || '',
  human: 'The booking was created at the new time, but the original at ' + R.old_start + ' could NOT be '
       + 'removed, so "' + R.title + '" is now on the calendar twice. Tell the requester exactly that and '
       + 'say the old one has to be deleted by hand.' } }];

const v = $input.first().json || {};
return [{ json: { status:'REJECTED', reason: v.reason || 'FAILED',
  human: v.human || 'Nothing was moved and the reason is unclear. Tell the requester it did not go through.' } }];

// Notification recipients for an authorized change: the booker (owner) always, plus the
// assigned engineer when distinct. DEV_REDIRECT reroutes to one dev inbox while building.
// ALLOW = ids that receive their OWN real DM instead of the redirect - but only as the
// BOOKER (honorAllow=true). The engineer notice always redirects while DEV_REDIRECT is set
// (honorAllow=false), so a tester is pinged only for bookings THEY made, not test bookings
// made FOR them. At launch DEV_REDIRECT='' and everyone (booker + engineer) is DM'd for real.
const DEV_REDIRECT = 'U08V3CKDGJF';                 // '' at launch
const ALLOW = ['U08V3CKDGJF','U098UFMKQHZ','U08JL17A50A','U0B4S0EKSAY','U098UFLG70B','U026N6E1R']; // Howard, Trish, Camy, Jess, Tel, Tara
const route = (id, honorAllow) => (!DEV_REDIRECT || (honorAllow && ALLOW.indexOf(id) !== -1)) ? id : DEV_REDIRECT;
const co = $('Resolve Booking').first().json;
const trig = $('When Executed by Another Workflow').first().json;
const actor = String(trig.requester_name || 'a coordinator');
const actorId = String(trig.requester || '');
const dateStr = String(trig.booking_date || '');
const title = co.title;
const VERB = 'moved';
const roomNote = co.roomNote || '';
const out = [];
const push = (id, name, body, honorAllow) => {
  const to = route(id, honorAllow); const redirected = to !== id;
  out.push({ to, text: (redirected ? ('[DEV] would notify ' + name + ' (' + id + '):\n') : '') + body });
};
const bookerId = co.bookerRef;
const bookerName = co.bookerName || 'the booker';
push(bookerId, bookerName, 'Heads up - your booking "' + title + '" on ' + dateStr + ' was ' + VERB + roomNote + ' by ' + actor + '.', true);
let eng = {};
try { eng = $('Lookup Engineer').first().json || {}; } catch (e) {}
const ef = eng.fields || {};
const engId = ef['Slack User ID'] || '';
const engName = ef['Name'] || '';
if (engId && engId !== bookerId && engId !== actorId) {
  push(engId, engName, 'Heads up - the session "' + title + '" you are assigned to on ' + dateStr + ' was ' + VERB + roomNote + ' by ' + actor + '.', false);
}
return out.map(o => ({ json: o }));

function manila(iso){ const d=iso?new Date(iso):new Date();
  const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(d).reduce((o,x)=>(o[x.type]=x.value,o),{});
  return p.year+'-'+p.month+'-'+p.day+' '+p.hour+':'+p.minute; }
function dateOnly(iso){ try{ return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(iso)); }catch(e){ return ''; } }
function timeRange(a,b){ const f=iso=>{ try{ return new Date(iso).toLocaleTimeString('en-US',{timeZone:'Asia/Manila',hour:'numeric',minute:'2-digit'}); }catch(e){ return ''; } };
  const s=f(a),e=f(b); return (s&&e)?(s+' \u2013 '+e):''; }

const RB = $('Resolve Booking').first().json || {};
const CR = $('Create Replacement').first().json || {};
const REQ = $('When Executed by Another Workflow').first().json || {};
return [{ json: {
  'Timestamp': manila(),
  'Action': 'MOVED',
  'Title': String(RB.title || ''),
  'Room(s)': String(RB.location || ''),
  'Date': dateOnly(RB.new_start),
  'Time': timeRange(RB.new_start, RB.new_end),
  'Department': '',
  'Booker': String(RB.bookerName || ''),
  'Done by': String(REQ.requester_name || RB.bookerName || ''),
  'Event ID': String(CR.id || ''),
  'Note': RB.roomNote ? ('moved' + RB.roomNote) : 'rescheduled'
} }];
